    is_delta_run = False

    if STUDENT_DELTA:
        try:
            trimmed = STUDENT_DELTA.strip()
            if trimmed.startswith("[") or trimmed.startswith("{"):
                payload = json.loads(trimmed)
                batches = payload if isinstance(payload, list) else [payload]
                for batch in batches:
                    nums = batch.get("StudentNumbers") or batch.get("studentnumbers")
                    if nums:
                        for sid in str(nums).split(","):
                            sid = sid.strip()
                            if sid:
                                parsed_sids.append(sid)
            else:
                parsed_sids = [sid.strip() for sid in STUDENT_DELTA.split(",") if sid.strip()]
        except Exception as ex:
            print(f"Warning: could not parse STUDENT_DELTA as JSON; falling back to simple split. {ex}")
            parsed_sids = [sid.strip() for sid in STUDENT_DELTA.split(",") if sid.strip()]

    # Apply threshold to total ID count across all batches
    _threshold = int(THRESHOLD) if THRESHOLD not in (None, "") else 2000
    total_ids = len(parsed_sids)

    if total_ids > _threshold:
        print(f"Student delta has {total_ids} IDs (> {_threshold}); using full load (no Student_Reference block).")
        parsed_sids = []
        is_delta_run = False
    elif total_ids > 0:
        print(f"Student delta has {total_ids} IDs (<= {_threshold}); using incremental by Student IDs.")
        is_delta_run = True

    if parsed_sids:
        parts = []
        for sid in parsed_sids:
            parts.append(
                f"""                <bsvc:Student_Reference>
                        <bsvc:ID bsvc:type=\"Student_ID\">{sid}</bsvc:ID>
                    </bsvc:Student_Reference>"""
            )
        student_refs_xml = "\n".join(parts)

    if overwrite_soap_body:
        soap_body = overwrite_soap_body
    elif response_body_block:
        request_refs_block = ""
        if student_refs_xml:
            request_refs_block = f"""            <bsvc:Request_References>
    {student_refs_xml}
                </bsvc:Request_References>
    """

        soap_body = f"""
                <soapenv:Envelope xmlns:soapenv=\"http://schemas.xmlsoap.org/soap/envelope/\" xmlns:bsvc=\"urn:com.workday/bsvc\">
                    <soapenv:Body>
                        <bsvc:{OPERATION_NAME}_Request xmlns:bsvc=\"urn:com.workday/bsvc\">
    {request_refs_block}                        <bsvc:Response_Filter>
                                <bsvc:Page>1</bsvc:Page>
                                <bsvc:Count>100</bsvc:Count>
                            </bsvc:Response_Filter>
                            {response_body_block}
                
                </bsvc:{OPERATION_NAME}_Request>
                    </soapenv:Body>
                </soapenv:Envelope>
        """
    else:
        soap_body = None

